//get the incoming raw serial text line
let incomingLine = msg.payload.toString().trim();

//check if the string is the output from a sensor reading packet, if it is then process it
if (incomingLine.includes("Temperature:") && incomingLine.includes("|")) {

    //isolate the sensor text out of the sentence structure
    //the usual line layout is like: Temperature: 23.80 °C | Humidity: 69.00 % | Water Level Distance: 9.88 cm | Soil Moisture Level: 796"
    let temperaturePart = incomingLine.split("Temperature: ")[1].split(" °C")[0];
    let humidityPart = incomingLine.split("Humidity: ")[1].split(" %")[0];
    let waterLevelPart = incomingLine.split("Water Level Distance: ")[1].split(" cm")[0];
    let soilMoisturePart = incomingLine.split("Soil Moisture Level: ")[1].trim();

    //cache variables inside memory storage
    flow.set("lastTemperature", temperaturePart);
    flow.set("lastHumidity", humidityPart);
    flow.set("lastWaterLevel", waterLevelPart);
    flow.set("lastSoilMoisture", soilMoisturePart);

    //format the variables so they are suitable for the chart
    let chartTemperature = { topic: "Temperature (°C)", payload: temperaturePart };
    let chartHumidity = { topic: "Humidity (%)", payload: humidityPart };
    let chartWaterLevel = { topic: "Water Distance (cm)", payload: waterLevelPart };
    let chartSoilMoisture = { topic: "Soil Moisture", payload: soilMoisturePart };


    //now route the filtered floating-point variables
    return [
        { payload: parseFloat(temperaturePart) },// Temperature Gauge
        { payload: parseFloat(humidityPart) },//Humidity Gauge
        { payload: parseFloat(waterLevelPart) },// Water level Gauge
        { payload: parseInt(soilMoisturePart) },//Soil Moisture Gauge
        [chartTemperature, chartHumidity, chartWaterLevel, chartSoilMoisture],
    ];
}



// any other unformatted serial logs or connection helper texts are disregarded
return null;

//pull the cached variables back out from flow state memory storage
//if a variable is empty, it safely defaults to 0.0 baseline indicators
return [
    { payload: flow.get("lastTemperature") || 0.0 },  //output 1 -> Temperature Gauge
    { payload: flow.get("lastHumidity") || 0.0 },   //output 2 -> Humidity Gauge
    { payload: flow.get("lastWaterLevel") || 0.0 }, //output 3 -> Water Level Gauge
    { payload: flow.get("lastSoilMoisture") || 0 }     //output 4 -> Soil Moisture Gauge
]

// define local prototype coordinate matrices
// use London Regents Park for disaster monitoring simulation as an example
let centerLat = 51.5284;
let centerLon = -0.1544;

//build the multi-node geospatial payload tracker arrays
let markers = [
    {
        command: "addmarker",
        name: "Sensor Node (Node 1)",
        lat: centerLat + 0.0005,
        lon: centerLon - 0.0004,
        iconColor: "green",
        layer: "Field Infrastructure",
        message: "Environment Sensor Node"
    },

    {
        command: "addmarker",
        name: "Mitigation Actor (Node 2)",
        lat: centerLat - 0.0004,
        lon: centerLon + 0.0005,
        iconColor: "darkred",
        layer: "Actuator Infrastructure",
        message: "Physical Servo Floodgate and Irrigation Pump Relays"
    },

    {
        command: "addmarker",
        name: "Alert Gateway Node (Node 3)",
        lat: centerLat,
        lon: centerLon,
        iconColor: "blue",
        layer: "Gateway Core",
        message: "Fuzzy Logic Edge Processor & Dashboards"
    }
];

//loop through each marker and push it to the map node
markers.forEach(function(marker) {
    node.send({ payload: marker });
});

//get the variable type and value to change it to
let command = msg.topic;
let value = msg.payload;

//dictionary mapping
//map the 8 thresholds to different characters
//skip 'F' as it will be used for the floodgate and 'I' for irrigation
let thresholdCharacters = {
    "set_temperatureWarning" : "A",
    "set_temperatureCritical" : "B",
    "set_humidityWarning" : "C",
    "set_humidityCritical": "D",
    "set_waterLevelWarning" : "E",
    "set_waterLevelCritical": "G",
    "set_soilMoistureWarning" : "H",
    "set_soilMoistureCritical": "J"
}

//handle environment state overrides
if(command == "set_state"){
    //package the data as a token
    //e.g. "S-1\n" will mean default auto, "S0\n" will mean force normal
    msg.payload = "S" + parseInt(value) + "\n";
    return msg;
}

//check if the incoming message topic maches one of the dictionary keys
//if it does 'package' it into a command that will be sent to serial port as input
if(thresholdCharacters[command]){
    //convert the numeric value into a float with 2dp
    //it will automatically be converted to string when concatenated
    let numericValue = parseFloat(value).toFixed(2);

    //package the data as a token
    //e.g. "A23\n" will mean change the temperature warning threshold to 23
    msg.payload = thresholdCharacters[command] + numericValue + "\n";

    //now route it to the Alert Node serial monitor through USB
    return msg;
}

//handle deep sleep duration changes
//normal sleep = X, warning sleep = Y, critical sleep = Z
if(command == "set_normalSleep"){
    let seconds = parseInt(value);
    msg.payload = "X" + seconds + "\n";
    return msg;
}
if(command == "set_warningSleep"){
    let seconds = parseInt(value);
    msg.payload = "Y" + seconds + "\n";
    return msg;
}
if(command == "set_criticalSleep"){
    let seconds = parseInt(value);
    msg.payload = "Z" + seconds + "\n";
    return msg;
}

//handle force mitigation actions
if(command == "set_floodgate" || "set_irrigation" || "set_releaseMitigation"){
    //token is simply the value as each state will have different value
    msg.payload = value + "\n";
    return msg;
}

return null;
